import numpy as np
from scipy.optimize import least_squares
one=np.ones_like(t)
P=np.column_stack([one,x,v,x**2,x**3,v**2,v**3,x*v])
def model(p):
    w,a1,a2=p
    ph=w*t+a1*x+a2*v
    A=np.column_stack([P,np.cos(ph),np.sin(ph)])
    c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    return dv_dt-A@c
best=None
for w0 in np.linspace(0.3,0.4,6):
  for a1 in [-1,0,1]:
    for a2 in [-1,0,1]:
        try:
            r=least_squares(model,[w0,a1,a2])
            e=np.mean(r.fun**2)/np.var(dv_dt)
            if best is None or e<best[0]: best=(e,r.x)
        except Exception as ex: pass
print(best)
